package com.friendinneed.presence; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*; import java.time.*; import java.util.*; import org.junit.jupiter.api.Test;
class PresenceServiceTest { @Test void savesOnlyTransitionsAndMeasuresReturn(){PresenceEventRepository repo=mock(PresenceEventRepository.class);UUID id=UUID.randomUUID();Instant then=Instant.parse("2026-01-01T10:00:00Z");when(repo.findTop1ByProfileIdOrderByCreatedAtDesc(id)).thenReturn(Optional.of(new PresenceEvent(id,PresenceStatus.AWAY,0,then)));PresenceService service=new PresenceService(repo,Clock.fixed(then.plusSeconds(2700),ZoneOffset.UTC));var result=service.recordPresence(id,PresenceStatus.PRESENT,1);assertTrue(result.changed());assertEquals(45,result.awayDuration().toMinutes());} }
